import{_ as a,o,c as i,a4 as t}from"./chunks/framework.CQGI5ZO3.js";const p=JSON.parse('{"title":"xs-changes(7)","description":"What changed in each version, with links to the backlog stories behind each entry.","frontmatter":{"title":"xs-changes(7)","description":"What changed in each version, with links to the backlog stories behind each entry.","manual":"xs-changes(7)","manualName":"Changelog","sectionNumber":"7"},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),n={name:"changelog.md"};function s(d,e,r,c,l,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="xs-changes-7" tabindex="-1">xs-changes(7) <a class="header-anchor" href="#xs-changes-7" aria-label="Permalink to &quot;xs-changes(7)&quot;">​</a></h1><div class="manual-deck"><strong>Changelog</strong><p>What changed in each version, with links to the backlog stories behind each entry.</p></div><h2 id="changes" tabindex="-1">CHANGES <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;CHANGES {#changes}&quot;">​</a></h2><p>All notable changes to xsync (the <code>xs</code> executable). Story IDs refer to <a href="https://github.com/s4njee/xsyncv4/blob/main/backlog.md" target="_blank" rel="noreferrer">backlog.md</a>, where each one has its verification evidence.</p><h3 id="unreleased-—-0-1-0-protocol-4" tabindex="-1">Unreleased — 0.1.0, protocol 4 <a class="header-anchor" href="#unreleased-—-0-1-0-protocol-4" aria-label="Permalink to &quot;Unreleased — 0.1.0, protocol 4&quot;">​</a></h3><p>No release has been tagged yet. This section covers everything up to the current <code>main</code>.</p><h4 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>The executable is now <code>xs</code> in every build, install and release (<code>xs-linux-amd64</code>, <code>xs-linux-arm64</code>, <code>xs-darwin-universal</code>). <code>XSYNC_*</code> environment variables and <code>~/.config/xsync/config</code> keep their names. Diagnostics name the executable <code>xs</code> too, for example <code>remote xs is not installed on HOST</code>.</li><li>Native remote transfers use protocol 4 and still interoperate with protocol-3 peers. Optional capabilities are negotiated as feature bits instead of requiring equal versions (R-06).</li><li>New byte-copied files are written to a temporary name and renamed after verification by default; <code>--no-atomic</code> writes them directly (T-11).</li><li>Progress is shown by default when stderr is a terminal, and stays off in scripts; <code>--no-progress</code> and <code>XSYNC_PROGRESS</code> override it (U-06).</li></ul><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>Automatic fallback to a real rsync for unsupported options, daemon URLs and remote hosts without a compatible <code>xs</code>, with a one-line notice; <code>--no-fallback</code> and <code>XSYNC_FALLBACK=0</code> for strict native runs (R-02).</li><li>Static release binaries for Linux amd64/arm64 and a macOS universal binary (R-03), explicit <code>xs --install HOST</code> (R-04), automatic helper lookup on the remote host (R-05), <code>cmake --install</code> with a generated manpage and zsh completion (R-07), IPv6 and unusual host specs (R-08), and personal defaults in <code>XSYNC_OPTS</code> and a config file (R-09).</li><li>Verified-prefix resume for <code>-P</code>/<code>--partial</code> (E-01); <code>--out-format</code>, <code>--log-file</code> and stable sorted script output (E-02); rsync-compatible itemization, including <code>-ii</code> (E-03).</li><li>Block-matching delta transfers for large changed files, locally and remotely (E-04).</li><li>Source listing and <code>--list-only</code> (E-05), and a bounded end-of-run error summary (E-06).</li><li><code>--bwlimit</code>, <code>--timeout</code> and keep-alives (E-07).</li><li>Filter rule sides, merge files, <code>-F</code>, <code>-C</code>, <code>--delete-after</code> and <code>-m</code> (E-08).</li><li><code>--files-from</code>, <code>-R</code> and <code>-0</code> (E-09).</li><li>Metadata beyond <code>-a</code>: <code>-H</code>, <code>-X</code>, <code>-A</code>, <code>-E</code>, <code>-U</code>, <code>-N</code>, <code>--fileflags</code>, <code>--chmod</code> and <code>--chown</code> (E-10).</li><li><code>-S</code> sparse files and <code>--link-dest</code> snapshots (E-11).</li><li>macOS dataless files, sockets and immutable files (E-12).</li><li>Prompt cancellation when stdout is closed, with exit 13 (E-13).</li><li>Calmer progress rows for small files (U-02), directory clone activity (U-03), receiver-acknowledged push progress (U-04), wire rate, compression ratio and the limiting stage (U-05), <code>--info=progress2</code> and <code>--progress=json</code> (U-07), explicit phases such as <code>deleting</code>, <code>verifying</code> and <code>waiting for receiver</code> (U-08), dry-run plan summaries (U-09), one size-unit rule everywhere (U-10), and suspend/resume with cursor restoration on every exit path (U-11).</li><li>A product page and manual in <code>sites/xsync</code>, generated from the executable’s help, the source and captured output.</li></ul><h4 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li>Repeated syncs into a destination inside the source no longer nest without limit (T-01).</li><li><code>host:~/path</code> and remote wildcards expand as with rsync (T-02, T-03).</li><li>Accepted-but-ignored options and silent attribute failures now fail or fall back visibly (T-04, T-05).</li><li>Files that change while being read are detected (T-06); <code>--delete</code> stops after source I/O errors (T-07); interrupted remote transfers clean up (T-08).</li><li>Disk-full handling, <code>-x</code> across mount points, case and Unicode name collisions, receiver symlink safety, Ctrl-C during remote transfers, and root-only paths are fixed and tested (T-09, T-10, T-12 to T-15).</li></ul><h4 id="known-gaps" tabindex="-1">Known gaps <a class="header-anchor" href="#known-gaps" aria-label="Permalink to &quot;Known gaps&quot;">​</a></h4><ul><li>Real-ssh end-to-end checks on every physical target are still partial (R-01). The manual terminal pass was skipped at the user’s request (U-01).</li><li>Performance work (P3) and the engineering base (P4) are open; see the backlog’s tier tables and <code>sites/xsync</code>’s development status page.</li></ul><h2 id="versions" tabindex="-1">VERSIONS OF THIS MANUAL <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;VERSIONS OF THIS MANUAL {#versions}&quot;">​</a></h2><p>No release has been tagged yet, so this manual describes the current <code>main</code>. When the first release is tagged, its manual will be kept under its own version, and this page will link to it.</p>',16)])])}const m=a(n,[["render",s]]);export{p as __pageData,m as default};
